summary as (
  select migration,
         count(*) filter (where present is not null) as total,
         count(*) filter (where present) as ok,
         string_agg(kind || ' ' || object, ', ' order by kind, object) filter (where present is false) as missing
  from probe group by migration
)
select migration as "миграция",
       case when total = 0 then 'ℹ️ нет проверяемых объектов'
            when missing is null then '✅ применена'
            when ok = 0 then '❌ НЕ применена'
            else '⚠️ частично' end as "статус",
       ok || '/' || total as "объектов",
       missing as "не_хватает"
from summary order by migration;
